from __future__ import annotations

import os
from pathlib import Path

os.environ.setdefault("MPLCONFIGDIR", "/tmp/class_7_matplotlib")

import matplotlib
import numpy as np
import pandas as pd

matplotlib.use("Agg")
import matplotlib.pyplot as plt
from get_data import assemble, consumption_and_inflation, load_fred, load_french

ROOT = Path(__file__).resolve().parent
DATA_DIR = ROOT / "data"
RESULTS_DIR = ROOT / "results"

FREQUENCIES = {
    "Quarterly": DATA_DIR / "quarterly_data.csv",
    "Annual": DATA_DIR / "annual_data.csv",
}

PORTFOLIO_COLUMNS = ["market"] + [
    f"{group}_{decile}"
    for group in ("bm", "size", "momentum")
    for decile in range(1, 11)
]


def load_frequency_data() -> dict[str, pd.DataFrame]:
    """Load every frequency once so all questions can use the same loop."""
    return {frequency: pd.read_csv(path) for frequency, path in FREQUENCIES.items()}


def load_covid_frequency_data() -> dict[str, pd.DataFrame]:
    """Build samples that retain 2020 and 2021 from the cached raw inputs."""
    quarterly, annual = assemble(
        load_fred(refresh=False),
        load_french(refresh=False),
        exclude_covid=False,
    )
    return {"Quarterly": quarterly, "Annual": annual}


def b1_statistics(data: pd.DataFrame, frequency: str) -> pd.Series:
    """Return the B1 moments, with every reported number multiplied by 100."""
    variables = data[["market", "consumption_growth"]].dropna()
    market = variables["market"]
    consumption = variables["consumption_growth"]
    periods_per_year = 4 if frequency == "Quarterly" else 1

    statistics = pd.Series(
        {
            "Mean log real market return": periods_per_year * market.mean(),
            "SD log real market return": np.sqrt(periods_per_year) * market.std(),
            "Mean log real consumption growth": periods_per_year
            * consumption.mean(),
            "SD log real consumption growth": np.sqrt(periods_per_year)
            * consumption.std(),
            "Covariance": periods_per_year * market.cov(consumption),
            "Correlation": market.corr(consumption),
        }
    )
    return 100 * statistics


def write_b1(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Calculate B1 for each frequency and save CSV and LaTeX results."""
    table = pd.DataFrame(
        {
            frequency: b1_statistics(data, frequency)
            for frequency, data in data_by_frequency.items()
        }
    )
    RESULTS_DIR.mkdir(parents=True, exist_ok=True)
    table.to_csv(
        RESULTS_DIR / "b1_consumption_market.csv",
        index_label="Statistic",
        float_format="%.4f",
    )

    latex = table.to_latex(
        column_format="lrr",
        float_format=lambda value: f"{value:.4f}",
        escape=True,
        caption="Consumption and market moments.",
        label="tab:b1_consumption_market",
        position="htbp",
    )
    latex = latex.replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b1_consumption_market.tex").write_text(latex)


def portfolio_label(column: str) -> str:
    """Turn data column names into compact labels for the B2 figures."""
    if column == "market":
        return "Market"
    group, decile = column.split("_")
    group_label = {"bm": "B/M", "size": "Size", "momentum": "Mom."}[group]
    return f"{group_label} {decile}"


def b2_sharpe_ratios(data: pd.DataFrame, frequency: str) -> pd.Series:
    """Estimate the lognormal Sharpe ratios defined in A1(b)."""
    excess_returns = data[PORTFOLIO_COLUMNS].sub(data["rf"], axis=0)
    sharpe_ratios = (
        excess_returns.mean() + 0.5 * excess_returns.var()
    ) / excess_returns.std()
    periods_per_year = 4 if frequency == "Quarterly" else 1
    return np.sqrt(periods_per_year) * sharpe_ratios


def plot_b2(sharpe_ratios: pd.Series, frequency: str) -> None:
    """Plot all 31 portfolio Sharpe ratios for one sampling frequency."""
    figure, axis = plt.subplots(figsize=(12, 5.5))
    deciles = range(1, 11)
    positions = range(10)
    width = 0.25
    groups = (
        ("bm", "B/M", "#4472C4", -width),
        ("size", "Size", "#ED7D31", 0),
        ("momentum", "Momentum", "#70AD47", width),
    )
    for group, label, color, offset in groups:
        values = [sharpe_ratios[f"{group}_{decile}"] for decile in deciles]
        axis.bar(
            [position + offset for position in positions],
            values,
            width=width,
            label=label,
            color=color,
        )

    axis.axhline(
        sharpe_ratios["market"],
        color="#222222",
        linewidth=1.5,
        linestyle="--",
        label="Market",
    )
    axis.axhline(0, color="black", linewidth=0.8)
    axis.set_xticks(list(positions), list(deciles))
    axis.set_xlabel("Decile")
    axis.set_ylabel("Annualized Sharpe ratio")
    axis.set_title(f"{frequency} Sharpe ratios")
    axis.legend(frameon=False, ncol=4)
    axis.grid(axis="y", alpha=0.25)
    figure.tight_layout()
    figure.savefig(
        RESULTS_DIR / f"b2_sharpe_ratios_{frequency.lower()}.pdf",
        bbox_inches="tight",
    )
    plt.close(figure)


def write_b2(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Calculate, plot, and report B2 Sharpe ratios at every frequency."""
    ratios = pd.DataFrame(
        {
            frequency: b2_sharpe_ratios(data, frequency)
            for frequency, data in data_by_frequency.items()
        }
    )
    RESULTS_DIR.mkdir(parents=True, exist_ok=True)
    display_ratios = ratios.rename(index=portfolio_label)
    display_ratios.to_csv(
        RESULTS_DIR / "b2_sharpe_ratios.csv",
        index_label="Portfolio",
        float_format="%.4f",
    )

    for frequency in ratios:
        plot_b2(ratios[frequency], frequency)

    maxima = []
    for frequency in ratios:
        portfolio = ratios[frequency].idxmax()
        maximum = ratios.loc[portfolio, frequency]
        maximum_label = (
            "Momentum, 10th decile"
            if portfolio == "momentum_10"
            else portfolio_label(portfolio)
        )
        maxima.append(
            f"{frequency} & {maximum_label} & {maximum:.4f} \\\\"
        )

    latex = "\n".join(
        [
            r"\begin{table}[htbp]",
            r"\centering",
            r"\caption{Highest annualized Sharpe ratio.}",
            r"\label{tab:b2_max_sharpe}",
            r"\begin{tabular}{llr}",
            r"\toprule",
            r"Frequency & Portfolio & Sharpe ratio \\",
            r"\midrule",
            *maxima,
            r"\bottomrule",
            r"\end{tabular}",
            r"\end{table}",
            "",
        ]
    )
    (RESULTS_DIR / "b2_max_sharpe.tex").write_text(latex)


def write_b3(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Report the minimum gamma implied by the maximum observed Sharpe ratio."""
    rows = []
    for frequency, data in data_by_frequency.items():
        periods_per_year = 4 if frequency == "Quarterly" else 1
        maximum_sharpe = b2_sharpe_ratios(data, frequency).max()
        consumption_sd = (
            np.sqrt(periods_per_year) * data["consumption_growth"].std()
        )
        rows.append(
            {
                "Frequency": frequency,
                "Maximum Sharpe ratio": maximum_sharpe,
                "Consumption growth SD": consumption_sd,
                "Minimum gamma": maximum_sharpe / consumption_sd,
            }
        )

    results = pd.DataFrame(rows).set_index("Frequency")
    results.index.name = None
    results.to_csv(
        RESULTS_DIR / "b3_minimum_gamma.csv",
        index_label="Frequency",
        float_format="%.4f",
    )
    latex = results.to_latex(
        column_format="lrrr",
        float_format=lambda value: f"{value:.4f}",
        escape=True,
        caption=(
            "Minimum risk aversion using annualized Sharpe ratios and "
            "consumption-growth volatility."
        ),
        label="tab:b3_minimum_gamma",
        position="htbp",
    )
    (RESULTS_DIR / "b3_minimum_gamma.tex").write_text(latex)


def b4_rates(data: pd.DataFrame, frequency: str) -> pd.DataFrame:
    """Compute observed and CCAPM-implied rates and premia for B4."""
    consumption_growth = data["consumption_growth"]
    periods_per_year = 4 if frequency == "Quarterly" else 1
    consumption_sd = np.sqrt(periods_per_year) * consumption_growth.std()
    gamma = b2_sharpe_ratios(data, frequency).max() / consumption_sd
    delta = 0.96 ** (1 / 4) if frequency == "Quarterly" else 0.96

    implied_rf = (
        -np.log(delta)
        + gamma * consumption_growth.mean()
        - 0.5 * gamma**2 * consumption_growth.var()
    )
    excess_returns = {
        "Market": data["market"] - data["rf"],
        "Size": data["size_1"] - data["size_10"],
        "Value": data["bm_10"] - data["bm_1"],
        "Momentum": data["momentum_10"] - data["momentum_1"],
    }

    values = {
        "Risk-free rate": {
            "Observed": data["rf"].mean(),
            "CCAPM": implied_rf,
        }
    }
    for asset, excess_return in excess_returns.items():
        values[f"{asset} premium"] = {
            "Observed": excess_return.mean() + 0.5 * excess_return.var(),
            "CCAPM": gamma * excess_return.cov(consumption_growth),
        }

    return 100 * periods_per_year * pd.DataFrame.from_dict(values, orient="index")


def write_b4(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Write the observed and model-implied B4 comparison table."""
    results = pd.concat(
        {
            frequency: b4_rates(data, frequency)
            for frequency, data in data_by_frequency.items()
        },
        axis=1,
    )
    results.columns.names = ["Frequency", "Estimate"]
    results.to_csv(
        RESULTS_DIR / "b4_model_implied_returns.csv",
        index_label="Rate or premium",
        float_format="%.4f",
    )
    latex = results.to_latex(
        column_format="lrrrr",
        float_format=lambda value: f"{value:.4f}",
        escape=True,
        multicolumn_format="c",
        caption=(
            "Annualized observed and CCAPM-implied rates and risk premia "
            "(percent)."
        ),
        label="tab:b4_model_implied_returns",
        position="htbp",
    )
    latex = latex.replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b4_model_implied_returns.tex").write_text(latex)


def b5_grid_search(data: pd.DataFrame, frequency: str) -> dict[str, object]:
    """Fit annual delta and gamma to the five annualized B4 moments."""
    periods_per_year = 4 if frequency == "Quarterly" else 1
    consumption = data["consumption_growth"]
    observed_table = b4_rates(data, frequency)
    observed = observed_table["Observed"].to_numpy()
    excess_returns = [
        data["market"] - data["rf"],
        data["size_1"] - data["size_10"],
        data["bm_10"] - data["bm_1"],
        data["momentum_10"] - data["momentum_1"],
    ]
    loadings = 100 * periods_per_year * np.array(
        [returns.cov(consumption) for returns in excess_returns]
    )

    # Delta is annual. Quarterly model moments use delta^(1/4), which after
    # annualization makes the discounting term equal to -log(delta).
    delta_grid = np.linspace(0.95, 0.9999, 2000)
    gamma_grid = np.linspace(0.0, 1000.0, 10001)
    fitted_premia = gamma_grid[:, None] * loadings[None, :]
    premia_sse = ((observed[1:] - fitted_premia) ** 2).sum(axis=1)
    best_sse = np.inf
    delta_index = gamma_index = 0
    best_rf = 0.0
    for candidate_gamma_index, gamma in enumerate(gamma_grid):
        fitted_rf_grid = 100 * (
            -np.log(delta_grid)
            + periods_per_year * gamma * consumption.mean()
            - 0.5 * periods_per_year * gamma**2 * consumption.var()
        )
        candidate_sse = (observed[0] - fitted_rf_grid) ** 2 + premia_sse[
            candidate_gamma_index
        ]
        candidate_delta_index = int(np.argmin(candidate_sse))
        if candidate_sse[candidate_delta_index] < best_sse:
            best_sse = candidate_sse[candidate_delta_index]
            delta_index = candidate_delta_index
            gamma_index = candidate_gamma_index
            best_rf = fitted_rf_grid[candidate_delta_index]
    fitted = np.r_[
        best_rf, fitted_premia[gamma_index]
    ]
    errors = observed - fitted
    return {
        "delta": delta_grid[delta_index],
        "gamma": gamma_grid[gamma_index],
        "observed": pd.Series(observed, index=observed_table.index),
        "fitted": pd.Series(fitted, index=observed_table.index),
        "errors": pd.Series(errors, index=observed_table.index),
        "mse": np.mean(errors**2),
    }


def write_b5(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Grid-search B5 parameters and write tables and a fit plot."""
    fits = {
        frequency: b5_grid_search(data, frequency)
        for frequency, data in data_by_frequency.items()
    }
    parameters = pd.DataFrame(
        {
            frequency: {
                r"$\delta$": fit["delta"],
                r"$\gamma$": fit["gamma"],
                "MSE": fit["mse"],
            }
            for frequency, fit in fits.items()
        }
    )
    errors = pd.DataFrame(
        {frequency: fit["errors"] for frequency, fit in fits.items()}
    )
    parameters.to_csv(
        RESULTS_DIR / "b5_grid_search_parameters.csv",
        index_label="Estimate",
        float_format="%.8g",
    )
    errors.to_csv(
        RESULTS_DIR / "b5_pricing_errors.csv",
        index_label="Moment",
        float_format="%.4f",
    )
    parameter_latex = parameters.to_latex(
        column_format="lrr",
        float_format=lambda value: (
            f"{value:.3e}" if 0 < abs(value) < 1e-3 else f"{value:.4f}"
        ),
        escape=False,
        caption="Grid-search estimates.",
        label="tab:b5_grid_search",
        position="htbp",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    error_latex = errors.to_latex(
        column_format="lrr",
        float_format=lambda value: f"{value:.4f}",
        escape=True,
        caption="Pricing errors",
        label="tab:b5_pricing_errors",
        position="htbp",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b5_grid_search_parameters.tex").write_text(parameter_latex)
    (RESULTS_DIR / "b5_pricing_errors.tex").write_text(error_latex)

    figure, axis = plt.subplots(figsize=(6.5, 5.5))
    colors = {"Quarterly": "#4472C4", "Annual": "#ED7D31"}
    for frequency, fit in fits.items():
        axis.scatter(
            fit["observed"], fit["fitted"], s=55, color=colors[frequency],
            label=frequency, zorder=3,
        )
        offsets = (5, 5) if frequency == "Quarterly" else (5, -11)
        for moment, observed_value, fitted_value in zip(
            fit["observed"].index, fit["observed"], fit["fitted"]
        ):
            label = moment.replace(" premium", "").replace("Risk-free rate", "Risk-free")
            axis.annotate(
                label,
                (observed_value, fitted_value),
                xytext=offsets,
                textcoords="offset points",
                fontsize=8,
                color=colors[frequency],
            )
    all_values = np.concatenate(
        [np.r_[fit["observed"], fit["fitted"]] for fit in fits.values()]
    )
    lower, upper = all_values.min(), all_values.max()
    padding = 0.05 * (upper - lower)
    endpoints = [lower - padding, upper + padding]
    axis.plot(endpoints, endpoints, color="black", linestyle="--", linewidth=1,
              label="45-degree line")
    axis.set_xlim(endpoints)
    axis.set_ylim(endpoints)
    axis.set_xlabel("Observed moment (percent)")
    axis.set_ylabel("Fitted moment (percent)")
    axis.set_title("Observed and fitted moments")
    axis.legend(frameon=False)
    axis.grid(alpha=0.25)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b5_observed_vs_fitted.pdf", bbox_inches="tight")
    plt.close(figure)


