def write_b6b(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Compute ultimate-consumption covariances and implied gamma for B6(b)."""
    quarterly = load_covid_frequency_data()["Quarterly"].copy()
    excess_market = quarterly["market"] - quarterly["rf"]
    covid_start = pd.Period("2020Q1", freq="Q")
    covid_end = pd.Period("2021Q4", freq="Q")
    rows = []

    for horizon in (1, 12):
        ultimate_growth = quarterly["consumption_growth"].iloc[::-1].rolling(
            window=horizon, min_periods=horizon
        ).sum().iloc[::-1]
        overlaps_covid = pd.Series(
            [
                period <= covid_end and period + horizon - 1 >= covid_start
                for period in quarterly.index
            ],
            index=quarterly.index,
        )
        matched = pd.concat(
            {
                "excess_market": excess_market,
                "ultimate_growth": ultimate_growth,
            },
            axis=1,
        ).loc[~overlaps_covid].dropna()

        covariance = matched["excess_market"].cov(matched["ultimate_growth"])
        market_premium = (
            matched["excess_market"].mean()
            + 0.5 * matched["excess_market"].var()
        )
        rows.append(
            {
                "Horizon": f"S = {horizon}",
                "Excess return (%)": 400 * market_premium,
                "Covariance": covariance,
                "Required gamma": market_premium / covariance,
            }
        )

    results = pd.DataFrame(rows).set_index("Horizon")
    results.index.name = None
    results.to_csv(
        RESULTS_DIR / "b6b_ultimate_consumption_risk.csv",
        index_label="Horizon",
        float_format="%.6f",
    )
    display_results = results.rename(
        columns={
            "Excess return (%)": r"Excess return (\%)",
            "Covariance": "Covariance",
            "Required gamma": r"$\gamma$",
        }
    )
    latex = display_results.to_latex(
        column_format="lrrr",
        formatters={
            r"Excess return (\%)": lambda value: f"{value:.4f}",
            "Covariance": lambda value: f"{value:.6f}",
            r"$\gamma$": lambda value: f"{value:.4f}",
        },
        escape=False,
        caption="Ultimate consumption risk and the market excess return.",
        label="tab:b6b_ultimate_consumption_risk",
        position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\small\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b6b_ultimate_consumption_risk.tex").write_text(latex)


def write_b6c(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Estimate cross-sectional ultimate-consumption-risk regressions."""
    quarterly = load_covid_frequency_data()["Quarterly"].copy()
    covid_start = pd.Period("2020Q1", freq="Q")
    covid_end = pd.Period("2021Q4", freq="Q")
    regressions = {}

    for horizon in (1, 12):
        ultimate_growth = quarterly["consumption_growth"].iloc[::-1].rolling(
            window=horizon, min_periods=horizon
        ).sum().iloc[::-1]
        overlaps_covid = pd.Series(
            [
                period <= covid_end and period + horizon - 1 >= covid_start
                for period in quarterly.index
            ],
            index=quarterly.index,
        )
        sample = quarterly.loc[~overlaps_covid].copy()
        sample["ultimate_growth"] = ultimate_growth.loc[~overlaps_covid]
        sample = sample.dropna(subset=["ultimate_growth"])
        excess = sample[PORTFOLIO_COLUMNS].sub(sample["rf"], axis=0)

        # Both axes are annualized and expressed in percentage points.
        premia = 400 * (excess.mean() + 0.5 * excess.var())
        covariances = 400 * excess.apply(
            lambda returns: returns.cov(sample["ultimate_growth"])
        )
        design = np.column_stack([np.ones(len(covariances)), covariances])
        intercept, gamma = np.linalg.lstsq(design, premia, rcond=None)[0]
        fitted = pd.Series(
            intercept + gamma * covariances,
            index=PORTFOLIO_COLUMNS,
        )
        residuals = premia - fitted
        r_squared = 1 - (residuals**2).sum() / (
            (premia - premia.mean()) ** 2
        ).sum()
        regressions[horizon] = {
            "premia": premia,
            "covariances": covariances,
            "fitted": fitted,
            "intercept": intercept,
            "gamma": gamma,
            "r_squared": r_squared,
            "sample": sample,
        }

    portfolio_results = pd.concat(
        {
            f"S = {horizon}": pd.DataFrame(
                {
                    "Risk premium (%)": result["premia"],
                    "Covariance": result["covariances"],
                    "Fitted premium (%)": result["fitted"],
                }
            )
            for horizon, result in regressions.items()
        },
        axis=1,
    )
    portfolio_results.index = [portfolio_label(column) for column in portfolio_results.index]
    portfolio_results.to_csv(
        RESULTS_DIR / "b6c_portfolio_regressions.csv",
        index_label="Portfolio",
        float_format="%.6f",
    )

    estimates = pd.DataFrame(
        {
            f"S = {horizon}": {
                r"$\gamma$": result["gamma"],
                r"Intercept (\%)": result["intercept"],
                r"$R^2$": result["r_squared"],
            }
            for horizon, result in regressions.items()
        }
    )
    estimates.to_csv(
        RESULTS_DIR / "b6c_cross_section_estimates.csv",
        index_label="Estimate",
        float_format="%.6f",
    )
    estimates_latex = estimates.to_latex(
        column_format="lrr",
        float_format=lambda value: f"{value:.4f}",
        escape=False,
        caption="Cross-sectional ultimate-consumption-risk regressions.",
        label="tab:b6c_estimates",
        position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b6c_cross_section_estimates.tex").write_text(estimates_latex)

    no_momentum_columns = ["market"] + [
        f"{group}_{decile}"
        for group in ("bm", "size")
        for decile in range(1, 11)
    ]
    no_momentum_estimates = {}
    for horizon, result in regressions.items():
        premia = result["premia"].loc[no_momentum_columns]
        covariances = result["covariances"].loc[no_momentum_columns]
        design = np.column_stack([np.ones(len(covariances)), covariances])
        intercept, gamma = np.linalg.lstsq(design, premia, rcond=None)[0]
        residuals = premia - (intercept + gamma * covariances)
        r_squared = 1 - (residuals**2).sum() / (
            (premia - premia.mean()) ** 2
        ).sum()
        no_momentum_estimates[f"S = {horizon}"] = {
            r"$\gamma$": gamma,
            r"Intercept (\%)": intercept,
            r"$R^2$": r_squared,
        }
    no_momentum_table = pd.DataFrame(no_momentum_estimates)
    no_momentum_table.to_csv(
        RESULTS_DIR / "b6c_cross_section_estimates_no_momentum.csv",
        index_label="Estimate",
        float_format="%.6f",
    )
    no_momentum_latex = no_momentum_table.to_latex(
        column_format="lrr",
        float_format=lambda value: f"{value:.4f}",
        escape=False,
        caption="Cross-sectional regressions excluding momentum portfolios.",
        label="tab:b6c_estimates_no_momentum",
        position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b6c_cross_section_estimates_no_momentum.tex").write_text(
        no_momentum_latex
    )

    comparison_rows = {}
    for horizon, result in regressions.items():
        sample = result["sample"]
        observed_spreads = {
            "Market": sample["market"] - sample["rf"],
            "Size": sample["size_1"] - sample["size_10"],
            "Value": sample["bm_10"] - sample["bm_1"],
            "Momentum": sample["momentum_10"] - sample["momentum_1"],
        }
        observed = {
            name: 400 * (returns.mean() + 0.5 * returns.var())
            for name, returns in observed_spreads.items()
        }
        fitted = result["fitted"]
        model = {
            "Market": fitted["market"],
            "Size": fitted["size_1"] - fitted["size_10"],
            "Value": fitted["bm_10"] - fitted["bm_1"],
            "Momentum": fitted["momentum_10"] - fitted["momentum_1"],
        }
        comparison_rows[(f"S = {horizon}", "Observed")] = pd.Series(observed)
        comparison_rows[(f"S = {horizon}", "Fitted")] = pd.Series(model)

    comparison = pd.DataFrame(comparison_rows)
    comparison.columns.names = ["Horizon", "Estimate"]
    comparison.to_csv(
        RESULTS_DIR / "b6c_premium_comparison.csv",
        index_label="Portfolio",
        float_format="%.4f",
    )
    comparison_latex = comparison.to_latex(
        column_format="lrrrr",
        float_format=lambda value: f"{value:.4f}",
        multicolumn_format="c",
        caption="Observed and fitted risk premia.",
        label="tab:b6c_premium_comparison",
        position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b6c_premium_comparison.tex").write_text(comparison_latex)

    figure, axes = plt.subplots(1, 2, figsize=(11, 4.8))
    group_specs = (
        (["market"], "Market", "#222222"),
        ([f"bm_{i}" for i in range(1, 11)], "B/M", "#4472C4"),
        ([f"size_{i}" for i in range(1, 11)], "Size", "#ED7D31"),
        ([f"momentum_{i}" for i in range(1, 11)], "Momentum", "#70AD47"),
    )
    for axis, (horizon, result) in zip(axes, regressions.items()):
        for columns, label, color in group_specs:
            axis.scatter(
                result["covariances"].loc[columns],
                result["premia"].loc[columns],
                color=color,
                s=34,
                label=label,
            )
        x_line = np.linspace(result["covariances"].min(), result["covariances"].max(), 100)
        axis.plot(
            x_line,
            result["intercept"] + result["gamma"] * x_line,
            color="black",
            linestyle="--",
            linewidth=1.2,
            label="Fitted line",
        )
        axis.set_title(f"S = {horizon}")
        axis.set_xlabel("Consumption covariance")
        axis.set_ylabel("Risk premium (%)")
        axis.grid(alpha=0.25)
    axes[0].legend(frameon=False, fontsize=8)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b6c_premia_covariances.pdf", bbox_inches="tight")
    plt.close(figure)


def write_b7(data_by_frequency: dict[str, pd.DataFrame]) -> None:
    """Construct the five annual measures and run the B7 regressions."""
    quarterly = load_covid_frequency_data()["Quarterly"].copy()
    excess = quarterly[PORTFOLIO_COLUMNS].sub(quarterly["rf"], axis=0)
    covid_start, covid_end = pd.Period("2020Q1"), pd.Period("2021Q4")
    measures = {}

    growth4 = quarterly["consumption_growth"].rolling(4, min_periods=4).sum()
    returns4 = excess.rolling(4, min_periods=4).sum()
    for quarter in range(1, 5):
        endpoints = quarterly.index[quarterly.index.quarter == quarter]
        valid = [
            not (end >= covid_start and end - 3 <= covid_end)
            for end in endpoints
        ]
        frame = returns4.loc[endpoints].copy()
        frame.insert(0, "consumption_growth", growth4.loc[endpoints])
        measures[f"Q{quarter}--Q{quarter}"] = frame.loc[valid].dropna()

    levels = consumption_and_inflation(load_fred(refresh=False))["consumption"]
    average_levels = levels.groupby(levels.index.year).mean()
    average_growth = np.log(average_levels).diff().rename("consumption_growth")
    next_year_growth = average_growth.shift(-1)
    consecutive_years = average_growth.index.to_series().shift(-1).sub(
        average_growth.index.to_series()
    ).eq(1)
    calendar_average_correlation = average_growth[consecutive_years].corr(
        next_year_growth[consecutive_years]
    )
    (RESULTS_DIR / "b7c_calendar_average_correlation.tex").write_text(
        f"{calendar_average_correlation:.4f}"
    )
    annual_returns = excess.groupby(excess.index.year).sum()
    counts = excess.groupby(excess.index.year).size()
    annual_returns = annual_returns.loc[counts[counts == 4].index]
    calendar = average_growth.to_frame().join(annual_returns, how="inner")
    measures["Calendar average"] = calendar.loc[
        ~calendar.index.isin([2020, 2021, 2022])
    ].dropna()

    universes = {
        "31 portfolios": PORTFOLIO_COLUMNS,
        "21 portfolios": ["market"]
        + [f"size_{i}" for i in range(1, 11)]
        + [f"bm_{i}" for i in range(1, 11)],
    }
    part_a_rows, regressions = [], {}
    for measure_name, frame in measures.items():
        consumption = frame["consumption_growth"]
        market = frame["market"]
        market_covariance = market.cov(consumption)
        market_premium = market.mean() + 0.5 * market.var()
        part_a_rows.append(
            {
                "Measure": measure_name,
                r"Consumption SD (\%)": 100 * consumption.std(),
                "Market correlation": market.corr(consumption),
                r"$\gamma$": market_premium / market_covariance,
            }
        )
        for universe_name, columns in universes.items():
            portfolio_returns = frame[columns]
            premia = 100 * (portfolio_returns.mean() + 0.5 * portfolio_returns.var())
            covariances = 100 * portfolio_returns.apply(
                lambda series: series.cov(consumption)
            )
            design = np.column_stack([np.ones(len(columns)), covariances])
            intercept, gamma = np.linalg.lstsq(design, premia, rcond=None)[0]
            fitted = pd.Series(intercept + gamma * covariances, index=columns)
            residuals = premia - fitted
            r_squared = 1 - (residuals**2).sum() / (
                (premia - premia.mean()) ** 2
            ).sum()
            regressions[(measure_name, universe_name)] = {
                "premia": premia,
                "covariances": covariances,
                "intercept": intercept,
                "gamma": gamma,
                "r_squared": r_squared,
            }

    part_a = pd.DataFrame(part_a_rows).set_index("Measure")
    part_a.index.name = None
    part_a.to_csv(RESULTS_DIR / "b7a_consumption_measures.csv", float_format="%.4f")
    part_a_latex = part_a.to_latex(
        column_format="lrrr", float_format=lambda value: f"{value:.4f}",
        escape=False, caption="Annual consumption-growth measures and market risk.",
        label="tab:b7a_measures", position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b7a_consumption_measures.tex").write_text(part_a_latex)

    regression_table = pd.DataFrame(
        {
            (universe, statistic): [regressions[(measure, universe)][key] for measure in measures]
            for universe in universes
            for statistic, key in (
                (r"$\gamma$", "gamma"),
                (r"Intercept (\%)", "intercept"),
                (r"$R^2$", "r_squared"),
            )
        },
        index=measures.keys(),
    )
    regression_table.columns.names = ["Assets", "Estimate"]
    regression_table.to_csv(
        RESULTS_DIR / "b7b_cross_section_estimates.csv", float_format="%.4f"
    )
    regression_latex = regression_table.to_latex(
        column_format="lrrrrrr", float_format=lambda value: f"{value:.4f}",
        escape=False, multicolumn_format="c",
        caption="Cross-sectional regressions across annual consumption measures.",
        label="tab:b7b_regressions", position="H",
    ).replace("\\begin{tabular}", "\\centering\n\\scriptsize\n\\begin{tabular}", 1)
    (RESULTS_DIR / "b7b_cross_section_estimates.tex").write_text(regression_latex)

    figure, axes = plt.subplots(1, 2, figsize=(11, 4.8))
    groups = (
        (["market"], "Market", "#222222"),
        ([f"bm_{i}" for i in range(1, 11)], "B/M", "#4472C4"),
        ([f"size_{i}" for i in range(1, 11)], "Size", "#ED7D31"),
        ([f"momentum_{i}" for i in range(1, 11)], "Momentum", "#70AD47"),
    )
    for axis, measure_name in zip(axes, ("Calendar average", "Q4--Q4")):
        result = regressions[(measure_name, "31 portfolios")]
        for columns, label, color in groups:
            axis.scatter(result["covariances"].loc[columns], result["premia"].loc[columns],
                         color=color, s=34, label=label)
        x_line = np.linspace(result["covariances"].min(), result["covariances"].max(), 100)
        axis.plot(x_line, result["intercept"] + result["gamma"] * x_line,
                  color="black", linestyle="--", linewidth=1.2, label="Fitted line")
        axis.set(title=measure_name, xlabel="Consumption covariance",
                 ylabel="Risk premium (%)")
        axis.grid(alpha=0.25)
    axes[0].legend(frameon=False, fontsize=8)
    figure.tight_layout()
    figure.savefig(RESULTS_DIR / "b7b_premia_covariances.pdf", bbox_inches="tight")
    plt.close(figure)


def main() -> None:
    data_by_frequency = load_frequency_data()

    # Add subsequent question functions to this loop as they are implemented.
    for question in (
        write_b1, write_b2, write_b3, write_b4, write_b5, write_b5a, write_b6a,
        write_b6b,
        write_b6c,
        write_b7,
    ):
        question(data_by_frequency)


if __name__ == "__main__":
    main()
